import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import org.jooq.DSLContext;
import org.jooq.test.benchmarks.local.PGQueryBenchmark.BenchmarkState;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.TearDown;
import org.openjdk.jmh.annotations.Warmup;
@Fork(value = 1, jvmArgsAppend = "-Dorg.jooq.no-logo=true")
@Warmup(iterations = 3, time = 3)
@Measurement(iterations = 7, time = 3)
public class JSONObjectVsArrayBenchmark {
    @State(Scope.Benchmark)
    public static class BenchmarkState {
        DSLContext ctx;
        Connection connection;
        Statement  statement;
        @Setup(Level.Trial)
        public void setup() throws Exception {
            // H2 setup
            connection = DriverManager.getConnection("jdbc:h2:mem:json-benchmark", "sa", "");
            ctx = DSL.using(connection);
            statement = connection.createStatement();
            statement.executeUpdate("drop table if exists t");
            statement.executeUpdate("create table t (number_column int, string_column varchar(100))");
            statement.executeUpdate("insert into t select i, i from system_range(1, 10) as t(i)");
            // PostgreSQL setup
//            try (InputStream is = BenchmarkState.class.getResourceAsStream("/config.postgres.properties")) {
//                Properties p = new Properties();
//                p.load(is);
//                Class.forName(p.getProperty("db.postgres.driver"));
//                connection = DriverManager.getConnection(
//                    p.getProperty("db.postgres.url"),
//                    p.getProperty("db.postgres.username"),
//                    p.getProperty("db.postgres.password")
//                );
//                ctx = DSL.using(connection);
//
//                statement = connection.createStatement();
//                statement.executeUpdate("drop table if exists t");
//                statement.executeUpdate("create table t (number_column int, string_column varchar(100))");
//                statement.executeUpdate("insert into t select i, i from generate_series(1, 10) as t(i)");
//            }
        }
        @TearDown(Level.Trial)
        public void teardown() throws Exception {
            statement.executeUpdate("drop table if exists t");
            statement.close();
            connection.close();
        }
    }
    // Just show that both methods really do the same thing
    public static void main(String[] args) throws Exception {
        JSONObjectVsArrayBenchmark f = new JSONObjectVsArrayBenchmark();
        BenchmarkState state = new BenchmarkState();
        state.setup();
        System.out.println(f.testJsonObject(state));
        System.out.println(f.testJsonArray(state));
    }
    record R(int n, String s) {}
    @Benchmark
    public List<R> testJsonObject(BenchmarkState state) throws SQLException {
        List<R> result = new ArrayList<>();
        try (ResultSet rs = state.statement.executeQuery(
            // H2 syntax (if only there was a way to abstract over syntax ;)
            """
            select
              json_arrayagg(json_object(
                key number_column value number_column,
                key string_column value string_column
              ))
            from t
            """
            // PostgreSQL syntax
//            """
//            select
//              json_agg(json_build_object(
//                number_column, number_column,
//                string_column, string_column
//              ))
//            from t
//            """
        )) {
            while (rs.next()) {
                new JSONParser(state.ctx, rs.getString(1), ch(result)).parse();
            }
        }
        return result;
    }
    @Benchmark
    public List<R> testJsonArray(BenchmarkState state) throws SQLException {
        List<R> result = new ArrayList<>();
        try (ResultSet rs = state.statement.executeQuery(
            // H2 syntax
            """
            select
              json_arrayagg(json_array(number_column, string_column))
            from t
            """
            // PostgreSQL syntax
//            """
//            select
//              json_agg(json_build_array(number_column, string_column))
//            from t
//            """
        )) {
            while (rs.next()) {
                new JSONParser(state.ctx, rs.getString(1), ch(result)).parse();
            }
        }
        return result;
    }
    private JSONContentHandler ch(List<R> result) {
        return new JSONContentHandler() {
            int level;
            int n;
            String s;
            @Override
            public void valueTrue() {
            }
            @Override
            public void valueString(String string) {
                s = string;
            }
            @Override
            public void valueNumber(String string) {
                n = Integer.parseInt(string);
            }
            @Override
            public void valueNull() {
            }
            @Override
            public void valueFalse() {
            }
            @Override
            public void startObject() {
                if (level >= 1) {
                    n = 0;
                    s = null;
                }
            }
            @Override
            public void startArray() {
                if (level++ >= 1) {
                    n = 0;
                    s = null;
                }
            }
            @Override
            public void property(String key) {
            }
            @Override
            public void endObject() {
                result.add(new R(n, s));
            }
            @Override
            public void endArray() {
                if (level-- >= 1) {
                    result.add(new R(n, s));
                }
            }
        };
    }
}

Every time you create a struct instance — like AnimeCharacter(name: "Naruto", powerLevel: 9000) — you're calling an initializer. Swift generates one for you automatically, but sometimes you need more control over how your struct is set up. That's where custom initializers come in. 🍥
The Default Memberwise Initializer
When you create a struct with properties, Swift automatically generates what's called a memberwise initializer — a special function that accepts each property as a parameter, in the order they're defined:
struct Ninja {
    let name: String
    let village: String
    let rank: Int
}
let naruto = Ninja(name: "Naruto", village: "Konoha", rank: 7)
Swift silently created Ninja(name:village:rank:) for us. We didn't have to write anything. That's convenient — but sometimes we want to take control of that process ourselves.
Writing Your Own Initializer
Here's how you write a custom initializer that does the same thing as the default one:
struct Ninja {
    let name: String
    let village: String
    let rank: Int
    init(name: String, village: String, rank: Int) {
        self.name = name
        self.village = village
        self.rank = rank
    }
}
A few important things to notice:
- 
No funckeyword — initializers look like functions but Swift treats them specially
- No return type — an initializer always returns an instance of the struct it belongs to
- 
self— we useself.nameto mean "thenameproperty of this instance," as opposed to thenameparameter coming in
That last point is really important. Without self, writing name = name would be confusing — is that assigning the property to the parameter, or the other way around? self.name = name makes it crystal clear: "assign the parameter name to my own property name."
Why Use self?
self refers to the current instance of the struct — the specific ninja, character, or object you're working with right now.
The most common place you'll use it is in initializers, exactly as above. Without it, you'd have to use awkward parameter naming to avoid the clash:
// Without self — clunky parameter names:
init(ninjaName: String, ninjaVillage: String, ninjaRank: Int) {
    name = ninjaName
    village = ninjaVillage
    rank = ninjaRank
}
// With self — clean, matching names:
init(name: String, village: String, rank: Int) {
    self.name = name
    self.village = village
    self.rank = rank
}
The self version is much more readable. Outside of initializers, you generally don't need self — Swift can figure out what you mean. But inside an initializer where property names and parameter names match, self is the clear, unambiguous solution.
The Golden Rule
There is one rule for initializers that Swift enforces strictly:
Every property must have a value by the time the initializer ends.
No exceptions. If you forget to assign a value to even one property, Swift will refuse to build your code.
struct Ninja {
    let name: String
    let village: String
    let rank: Int
    init(name: String, village: String) {
        self.name = name
        self.village = village
        // ❌ rank was never assigned — Swift won't build this!
    }
}
You can satisfy this rule by assigning a value directly in the initializer, or by giving the property a default value when you declare it.
Custom Initializers With Different Behavior
The real power of custom initializers is that they don't have to work the same way as the default one. For example, what if every new ninja is automatically assigned a random mission rank between 1 and 10?
struct Ninja {
    let name: String
    let village: String
    let missionRank: Int
    init(name: String, village: String) {
        self.name = name
        self.village = village
        self.missionRank = Int.random(in: 1...10) // assigned automatically!
    }
}
let sakura = Ninja(name: "Sakura", village: "Konoha")
print(sakura.missionRank) // random number between 1 and 10
We provide name and village — Swift generates missionRank for us inside the initializer. The golden rule is still satisfied because all three properties get a value before the initializer ends.
Multiple Initializers
You can have more than one initializer in a struct — useful when you want to create instances in different ways:
struct Ninja {
    let name: String
    let village: String
    // Create a named ninja from a specific village
    init(name: String, village: String) {
        self.name = name
        self.village = village
    }
    // Create a mysterious unknown ninja
    init() {
        self.name = "???"
        self.village = "Unknown"
    }
}
let kakashi = Ninja(name: "Kakashi", village: "Konoha")
let mystery = Ninja() // name: "???", village: "Unknown"
The Catch: Custom Initializers Remove the Default One
Here's something important: as soon as you write your own initializer, Swift removes the automatically generated memberwise initializer.
struct Ninja {
    let name: String
    let village: String
    init() {
        self.name = "???"
        self.village = "Unknown"
    }
}
let kakashi = Ninja(name: "Kakashi", village: "Konoha") // ❌ No longer available!
let mystery = Ninja() // ✅ Works fine
Swift does this deliberately — if you wrote a custom initializer, it assumes that's your intended setup process, and the default one might skip important steps.
If you want to keep both the default memberwise initializer and your custom one, move the custom initializer into an extension:
struct Ninja {
    let name: String
    let village: String
}
extension Ninja {
    init() {
        self.name = "???"
        self.village = "Unknown"
    }
}
let kakashi = Ninja(name: "Kakashi", village: "Konoha") // ✅ Still works!
let mystery = Ninja() // ✅ Custom one works too!
By putting the custom initializer in an extension, Swift keeps the automatically generated memberwise initializer in place alongside it. Both are available. 🎉
Wrap Up
| Concept | What It Means | 
|---|---|
| Memberwise initializer | Auto-generated by Swift — accepts each property as a parameter | 
| Custom initializer | Written by you — init()with nofunckeyword and no return type | 
| self | Refers to the current instance — used to distinguish property names from parameter names | 
| Golden rule | Every property must have a value by the end of the initializer | 
| Extension trick | Add a custom init in an extension to keep the default memberwise init too | 
This article was written by me; AI was used to improve grammar and readability.

🚀 Build Your First Space Shooter Game with Limn Engine
A Complete Step-by-Step Tutorial for JavaScript Beginners
Welcome! In this tutorial, you'll build a complete space shooter game using Limn Engine — a zero‑configuration 2D game engine that runs in your browser.
What you'll build: A spaceship that moves, shoots bullets, fights waves of enemies, and keeps score. All in about 100 lines of code.
By the end, you'll understand:
- How to create a game loop
- How to handle keyboard input
- How to detect collisions
- How to use particles for visual effects
- How to manage game state (lives, score, game over)
🎮 Want to play the finished game? Click here to play Space Shooter Live!
Before We Start
What You Need
- A text editor (VS Code, Notepad, or any code editor)
- A web browser (Chrome, Firefox, Edge)
- Limn Engine — download epic.jsfrom limn-engine-doc.vercel.app
What You Should Know
- Basic JavaScript (variables, functions, arrays, if-statements)
- How to open an HTML file in a browser
No game development experience required!
Step 1: The HTML Structure
Every Limn Engine game starts with a simple HTML file.
<!doctype html>
<html>
  <head>
    <script src="asset/epic.js"></script>
  </head>
  <body>
  <script>
    // All your game code goes here
  </script>
  </body>
</html>
What's happening:
- 
<script src="asset/epic.js">— loads the Limn Engine library
- Everything inside the second <script>tag is your game code
Save this as game.html and open it in your browser. You should see a blank canvas with a blue gradient background.
Step 2: Setting Up the Game
The first thing we need is a Display — this is the engine that creates the canvas, runs the game loop, and handles input.
const display = new Display();
display.perform();        // Activates performance mode (dual-canvas rendering)
display.start(800, 600);  // Creates an 800×600 canvas
What's happening:
- 
new Display()— creates the engine
- 
display.perform()— turns on high-performance mode
- 
display.start(800, 600)— creates a canvas 800 pixels wide and 600 pixels tall
Add this code now. If you refresh your browser, you'll see a black canvas.
Step 3: Creating the Player
Every visible object in Limn Engine is a Component — that includes the player, enemies, bullets, and even text.
const player = new Component(40, 40, "cyan", 400, 520, "rect");
display.add(player);
Breakdown:
| Parameter | Value | Meaning |
|-----------|-------|---------|
| 40, 40 | width, height | The player is a 40×40 pixel square |
| "cyan" | color | The player is cyan (light blue) |
| 400, 520 | x, y | Position at 400px from left, 520px from top |
| "rect" | type | It's a rectangle (shape) |
Add this code. Now when you refresh, you'll see a cyan square near the bottom of the screen.
Step 4: Adding a Background
Let's make the background look like space.
display.lgradient("top", "royalblue", "darkblue");
Breakdown:
- 
lgradient— linear gradient (colors blend from one to another)
- 
"top"— the gradient goes from top to bottom
- 
"royalblue"— top color (light blue)
- 
"darkblue"— bottom color (dark blue)
Add this code below display.start(). Your game now has a space sky background.
Step 5: Adding UI — Score and Lives
We need to display the score and remaining lives. For text, we use Tctxt — a special component for text.
const scoreText = new Tctxt("32px", "Arial", "white", 20, 50);
scoreText.setText("Score: 0");
display.add(scoreText);
const livesText = new Tctxt("24px", "Arial", "red", 20, 100);
livesText.setText("Lives: 3: "+" Bullets: 12");
display.add(livesText);
Breakdown:
| Parameter | scoreText | livesText |
|-----------|-----------|-----------|
| "32px" / "24px" | Font size | Smaller for lives |
| "Arial" | Font family | Same font |
| "white" / "red" | Text color | Score is white, lives are red |
| 20, 50 | Position | Score at top-left |
| 20, 100 | Position | Lives below score |
Add this code. Now you have a score and lives display.
Step 6: Adding Particles
We need particles for visual effects like explosions and engine exhaust.
const particles = new ParticleSystem(display);
What's happening:
- 
new ParticleSystem(display)— creates a particle system linked to our display
- We'll use this later for explosions and the engine trail
Add this code after creating the display.
Step 7: Game Variables
We need variables to track the game state:
let enemies = [];          // Array to hold all enemies
let bullets = [];          // Array to hold all bullets
let score = 0;             // Player's score
let lives = 3;             // Player's lives
let enemyTimer = 0;        // Timer for spawning enemies
let invincibleFrames = 0;  // Frames of invincibility after being hit
let bulletCounts = 12;     // How many bullets the player has
Add this code after your UI setup.
Step 8: Creating the Update Function
The update function is called 60 times per second — it's where all the game logic happens.
function update(dt) {
    // All game logic goes here
}
What is dt? dt stands for "delta time" — the time since the last frame. It's very small (around 0.016 seconds at 60 FPS). We multiply speeds by dt so the game runs at the same speed on all devices.
Add this empty function after your game variables.
Step 9: Making the Player Move
Inside the update function, let's handle player movement:
function update(dt) {
    // Player movement
    if (display.keys[37]) {         // Left arrow key
        player.speedX = -400 * dt;
    } else if (display.keys[39]) {  // Right arrow key
        player.speedX = 400 * dt;
    } else {
        player.speedX = 0;
    }
    // Keep player on screen
    move.bound(player);
}
Key codes:
- 
37— Left arrow
- 
39— Right arrow
What's happening:
- If the left arrow is pressed, the player moves left at 400 pixels per second
- If the right arrow is pressed, the player moves right at 400 pixels per second
- If neither is pressed, the player stops
- 
move.bound(player)— prevents the player from going off-screen
Test your game: You can now move the player left and right!
Step 10: Creating Enemies
We need enemies that come from the top of the screen:
function createEnemy() {
    const e = new Component(35, 35, "red", Math.random() * 750, -35, "rect");
    e.speedY = 1.50;
    display.add(e);
    enemies.push(e);
}
Breakdown:
- 
Math.random() * 750— random X position across the screen
- 
-35— starts above the screen
- 
e.speedY = 1.50— moves downward at 1.5 pixels per frame
Now add this to the update function:
function update(dt) {
    // ... existing code ...
    // Spawn enemies
    enemyTimer++;
    if (enemyTimer > 45) {
        enemyTimer = 0;
        createEnemy();
    }
}
What's happening:
- Every 45 frames (about 0.75 seconds), a new enemy appears
- Enemies spawn at a random X position above the screen
- They move downward
Step 11: Shooting Bullets
We need a function to create bullets:
function shoot() {
    if (bulletCounts > 0) {
        // Create bullet at player's position
        const b = new Component(5, 10, "yellow", player.x + 17.5, player.y, "rect");
        b.speedY = -5.00;
        display.add(b);
        bullets.push(b);
        bulletCounts--;
        livesText.setText("Lives: " + lives + ", Bullet: " + bulletCounts);
    }
}
Breakdown:
- 
player.x + 17.5— centers the bullet on the player (half of player width)
- 
b.speedY = -5.00— bullet moves upward
- 
bulletCounts--— uses one bullet
Now add this to the update function:
function update(dt) {
    // ... existing code ...
    // Shoot with SPACE
    if (display.keys[32]) {
        shoot();
        display.keys[32] = false;  // Prevent holding down SPACE
    }
}
Key code: 32 = Spacebar
What's happening:
- When SPACE is pressed, we call shoot()
- A bullet appears at the player's position
- The bullet travels upward
- 
bulletCountsdecreases and the UI updates
- 
display.keys[32] = false— ensures one bullet per press
Step 12: Refilling Bullets
We want bullets to refill every 7 seconds:
setInterval(() => {
    bulletCounts = 12;
}, 7000);
What's happening:
- Every 7 seconds (7000 milliseconds), bullets reset to 12
Step 13: Updating Bullets
Bullets need to move upward and be removed when off-screen:
function update(dt) {
    // ... existing code ...
    // Update bullets
    for (let i = 0; i < bullets.length; i++) {
        bullets[i].y += bullets[i].speedY * dt;
        if (bullets[i].y < -50) {
            bullets[i].hide();        // Hide from view
            bullets.splice(i, 1);     // Remove from array
            i--;
        }
    }
}
What's happening:
- Each bullet moves upward at its speed
- If a bullet goes above the screen (y < -50), it's hidden and removed from the array
Step 14: Enemy Logic and Collisions
This is the most important part — handling enemy movement and collisions:
function update(dt) {
    // ... existing code ...
    // Update enemies
    for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        e.y += e.speedY * dt;
        // Enemy vs player collision
        if (e.crashWith(player) && invincibleFrames === 0) {
            lives--;
            livesText.setText("Lives: " + lives + ", Bullet: " + bulletCounts);
            invincibleFrames = 60;
            display.camera.shake(8, 8);
            e.hide();
            enemies.splice(i, 1);
            i--;
            if (lives <= 0) {
                display.stop();
                alert("Game Over! Score: " + score);
                location.reload();
            }
            continue;
        }
        // Enemy vs bullet collision
        for (let j = 0; j < bullets.length; j++) {
            if (e.crashWith(bullets[j])) {
                move.particles.explosion(particles, e.x, e.y, 20);
                score += 10;
                scoreText.setText("Score: " + score);
                display.camera.shake(3, 3);
                e.hide();
                bullets[j].hide();
                enemies.splice(i, 1);
                bullets.splice(j, 1);
                i--;
                break;
            }
        }
        // Enemy escapes bottom
        if (enemies[i] && enemies[i].y > 650) {
            enemies[i].hide();
            score -= 12;
            scoreText.setText("Score: " + score);
            enemies.splice(i, 1);
            i--;
            if (score < 0) {
                display.stop();
                alert("Game Over! Score: " + score);
                location.reload();
            }
        }
    }
}
What's happening:
- Enemies move down the screen
- If enemy hits player: Lose a life, become invincible, screen shakes
- If bullet hits enemy: Explosion, +10 score, screen shakes
- If enemy escapes: -12 score, game over if score goes negative
Step 15: Invincibility and Camera Follow
Add invincibility flashing and camera follow:
function update(dt) {
    // Update particles
    particles.update();
    // Camera follows player
    display.camera.follow(player);
    // Invincibility blinking
    if (invincibleFrames > 0) {
        invincibleFrames--;
        player.alpha = 0.5;  // Semi-transparent
    } else {
        player.alpha = 1;    // Fully visible
    }
}
Note: In Limn Engine, alpha controls transparency. 1 is fully visible, 0.5 is half-transparent.
Step 16: Engine Exhaust Particles
Add a trail of particles behind the player:
function update(dt) {
    // ... existing code ...
    // Engine exhaust particles
    particles.emit(player.x + 20, player.y + 40, {
        color: "orange",
        life: 15,
        alphaFade: 0.07,
        speedY: 1,
        width: 5,
        height: 5,
        type: "circle"
    });
}
Particle options explained:
| Option | Value | Meaning |
|--------|-------|---------|
| color | "orange" | The particle color |
| life | 15 | Lives for 15 frames |
| alphaFade | 0.07 | Fades out gradually |
| speedY | 1 | Drifts downward slightly |
| width/height | 5 | Particle size |
| type | "circle" | Round particles |
